    "swap": {
      "result": "pass",
      "reason": "The sequence rests on Ines’s ferment log, prep-led menu, koji cupboard, Brine and grandmother’s pot."
    },
    "backdrop": {
      "result": "fail",
      "reason": "Deleting the jar animation preserves the log, narrative and all practical information, losing primarily visual atmosphere."
    },
